int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q;
    string S;
    cin >> N >> S;
    cin >> Q;
    vector<int> ks(Q);
    int max_k = 0;
    for (int i = 0; i < Q; i++) {
        cin >> ks[i];
        max_k = max(max_k, ks[i]);
    }

    // prefix count of M
    vector<int> prefM(N + 1, 0);
    for (int i = 0; i < N; i++) {
        prefM[i + 1] = prefM[i] + (S[i] == 'M');
    }

    // For each D position, for each C to the right within max_k distance,
    // we can accumulate contributions per k.
    vector<long long> ans(max_k + 1, 0);

    for (int a = 0; a < N; a++) {
        if (S[a] != 'D') continue;
        for (int c = a + 2; c < N && c - a <= max_k; c++) {
            if (S[c] != 'C') continue;
            int cntM = prefM[c] - prefM[a + 1];
            if (cntM > 0) {
                int dist = c - a;
                // This triple is counted for all k >= dist
                ans[dist] += cntM;
            }
        }
    }

    // accumulate for increasing k
    for (int k = 1; k <= max_k; k++) {
        ans[k] += ans[k - 1];
    }

    for (int k : ks) {
        cout << ans[k] << "\n";
    }

    return 0;
