#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    string S;
    cin >> S;

    int Q;
    cin >> Q;

    while (Q--) {
        long long k;
        cin >> k;

        long long ans = 0;
        long long dCnt = 0;      // number of 'D' in current window [i-k+1, i-1]
        long long dmCnt = 0;     // number of pairs (D, M) in current window with D before M

        for (int i = 0; i < N; ++i) {
            // Remove position out of allowed range: j <= i-k
            int out = i - (int)k;
            if (out >= 0) {
                if (S[out] == 'D') {
                    dCnt--;
                } else if (S[out] == 'M') {
                    // This M had contributed with all D before it still in window at that time.
                    // After sliding, remove pairs using D in current window before this M.
                    // Easier correct way: process removal before adding current char,
                    // and when removing M, subtract number of D currently in window.
                    // To achieve correctness, we need window state after removing older chars only.
                    dmCnt -= dCnt;
                }
            }

            if (S[i] == 'D') {
                dCnt++;
            } else if (S[i] == 'M') {
                dmCnt += dCnt;
            } else if (S[i] == 'C') {
                ans += dmCnt;
            }
        }

        cout << ans << '\n';
    }

    return 0;
}

