#define MAXN 1000005

int main() {
    int N, Q;
    char S[MAXN];
    scanf("%d", &N);
    scanf("%s", S);
    scanf("%d", &Q);

    // Precompute prefix counts for D and M
    int prefixD[MAXN+1] = {0};
    int prefixM[MAXN+1] = {0};

    for (int i = 0; i < N; i++) {
        prefixD[i+1] = prefixD[i] + (S[i] == 'D');
        prefixM[i+1] = prefixM[i] + (S[i] == 'M');
    }

    // For each k, we process queries
    while (Q--) {
        int k;
        scanf("%d", &k);

        long long ans = 0;

        // Iterate over each 'C' position
        for (int c = 0; c < N; c++) {
            if (S[c] != 'C') continue;

            // We need a < b < c and c - a < k, so a > c - k
            int minA = (c - k + 1) > 0 ? (c - k + 1) : 0;

            // Count D's in range [minA, c-1] and M's in range [minA+1, c-1]
            // For each D at position a, we need M's in (a, c)
            // Sum over a of (M count in (a, c))

            // Let's use two-pointer technique or prefix sums
            // For each possible a, number of M's between a+1 and c-1
            // = prefixM[c] - prefixM[a+1]

            // So total = sum_{a in [minA, c-1], S[a]=='D'} (prefixM[c] - prefixM[a+1])
            // = prefixM[c] * (count of D in range) - sum_{a in D positions} prefixM[a+1]

            // We can compute this efficiently with prefix sums of prefixM at D positions

            // For each c, we can just iterate over possible a if k is small,
            // but for large N we need O(N) per query.

            // Alternative: For each D, we can add contributions to future C's.
        }

        // Simpler approach: For each query, iterate over all possible D-M-C combinations
        // but that's O(N^3). Need smarter.

        // Let's use the fact that we can precompute for each position the count
        // of pairs (D, M) with certain constraints.

        // Actually, let's do it differently: for each D, for each M after it,
        // count C's within k distance from D.

        // Reset answer
        ans = 0;

        // For each D position
        for (int a = 0; a < N; a++) {
            if (S[a] != 'D') continue;

            // For each M position after D
            for (int b = a+1; b < N; b++) {
                if (S[b] != 'M') continue;

                // Count C's in [b+1, min(N-1, a+k-1)]
                int maxC = (a + k - 1 < N) ? a + k - 1 : N - 1;
                if (maxC > b) {
                    // Count C's from b+1 to maxC
                    for (int c = b+1; c <= maxC; c++) {
                        if (S[c] == 'C') ans++;
                    }
                }
            }
        }

        printf("%lld\n", ans);
    }

    return 0;
}

