int main() {
    int N, Q;
    scanf("%d", &N);
    char *S = malloc(N + 2);
    scanf("%s", S);
    scanf("%d", &Q);

    long long *prefM = calloc(N + 1, sizeof(long long));
    for (int i = 0; i < N; i++) {
        prefM[i+1] = prefM[i] + (S[i] == 'M' ? 1 : 0);
    }

    // f[d] = sum over a where S[a]='D' and S[a+d]='C' of (prefM[a+d] - prefM[a+1])
    long long *f = calloc(N + 1, sizeof(long long));

    for (int a = 0; a < N; a++) {
        if (S[a] != 'D') continue;
        for (int c = a + 1; c < N; c++) {
            if (S[c] != 'C') continue;
            int d = c - a;
            f[d] += prefM[c] - prefM[a+1];
        }
    }

    // prefix sum of f: ans[k] = sum_{d=1}^{k-1} f[d]
    long long *ans = calloc(N + 2, sizeof(long long));
    for (int d = 1; d < N; d++) {
        ans[d+1] = ans[d] + f[d];
    }
    // ans[k] = answer for query k (for k >= 1)

    for (int q = 0; q < Q; q++) {
        int k;
        scanf("%d", &k);
        long long result = 0;
        if (k <= N) result = ans[k];
        else result = ans[N];
        printf("%lld\n", result);
    }

    free(S); free(prefM); free(f); free(ans);
    return 0;
}

