int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    char *S = (char *)malloc((N + 5) * sizeof(char));
    scanf("%s", S);

    int Q;
    scanf("%d", &Q);

    while (Q--) {
        int k;
        scanf("%d", &k);

        long long cntD = 0;      // number of 'D' in current window [i-k+1, i-1]
        long long cntM = 0;      // number of 'M' in current window
        long long cntDM = 0;     // number of pairs (D,M) in current window with D before M
        long long ans = 0;

        for (int i = 0; i < N; i++) {
            int out = i - k;
            if (out >= 0) {
                if (S[out] == 'D') {
                    cntD--;
                } else if (S[out] == 'M') {
                    cntM--;
                    // remove pairs formed by D before this M within remaining window
                    long long d_before = 0;
                    // number of D in window positions [out+1, i-1]
                    // after decrementing cntM, cntD already excludes removed D if any
                    // to get D before position out among current window is not needed;
                    // instead use standard sliding update order:
                    // remove contribution of this M with D before it in old window.
                    // We maintain this by storing prefix count of D.
                }
            }
        }

        // The above direct removal for cntDM is tricky without extra info.
        // Use equivalent O(N) two-pointer/prefix method:
        long long *prefD = (long long *)malloc((N + 1) * sizeof(long long));
        long long *prefM = (long long *)malloc((N + 1) * sizeof(long long));
        long long *prefDM = (long long *)malloc((N + 1) * sizeof(long long));

        prefD[0] = 0;
        prefM[0] = 0;
        prefDM[0] = 0;

        for (int i = 0; i < N; i++) {
            prefD[i + 1] = prefD[i] + (S[i] == 'D');
            prefM[i + 1] = prefM[i] + (S[i] == 'M');
            prefDM[i + 1] = prefDM[i];
            if (S[i] == 'M') prefDM[i + 1] += prefD[i];
        }

        ans = 0;
        for (int c = 0; c < N; c++) {
            if (S[c] != 'C') continue;
            int L = c - k + 1;
            if (L < 0) L = 0;

            // Count pairs (a,b) with L <= a < b < c, S[a]='D', S[b]='M'
            // = total DM pairs in [0, c) minus those with a < L
            // total in [0,c): prefDM[c]
            // bad pairs:
            // 1) b < c and b >= L, a < L -> prefD[L] * (#M in [L,c))
            // 2) b < L already included in prefDM[L]
            long long totalDMBeforeC = prefDM[c];
            long long badInsideLeft = prefDM[L];
            long long badCross = prefD[L] * (prefM[c] - prefM[L]);
            long long good = totalDMBeforeC - badInsideLeft - badCross;

            ans += good;
        }

        printf("%lld\n", ans);

        free(prefD);
        free(prefM);
        free(prefDM);
    }

    free(S);
    return 0;
}

