public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine());
        String S = br.readLine();
        int Q = Integer.parseInt(br.readLine());

        int[] prefixD = new int[N + 1];
        int[] prefixC = new int[N + 1];
        for (int i = 0; i < N; i++) {
            prefixD[i + 1] = prefixD[i] + (S.charAt(i) == 'D' ? 1 : 0);
            prefixC[i + 1] = prefixC[i] + (S.charAt(i) == 'C' ? 1 : 0);
        }

        StringBuilder sb = new StringBuilder();
        for (int q = 0; q < Q; q++) {
            int k = Integer.parseInt(br.readLine());
            long ans = 0;

            // For each possible position of 'M'
            for (int b = 0; b < N; b++) {
                if (S.charAt(b) != 'M') continue;
                // a can be from max(0, b - k + 1) to b-1
                // c can be from b+1 to min(N-1, b + k - 1)
                int leftStart = Math.max(0, b - k + 1);
                int leftEnd = b - 1;
                int rightStart = b + 1;
                int rightEnd = Math.min(N - 1, b + k - 1);

                if (leftStart > leftEnd || rightStart > rightEnd) continue;

                long dCount = prefixD[leftEnd + 1] - prefixD[leftStart];
                long cCount = prefixC[rightEnd + 1] - prefixC[rightStart];
                ans += dCount * cCount;
            }
            sb.append(ans).append('\n');
        }
        System.out.print(sb.toString());
    }
}

import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String S = br.readLine().trim();
        int N = S.length();

        int[] prefM = new int[N + 1];
        for (int i = 0; i < N; i++) {
            prefM[i + 1] = prefM[i] + (S.charAt(i) == 'M' ? 1 : 0);
        }

        // contribution[d] = sum of count_M(a+1,c-1) for all (a,c) with c-a=d, S[a]='D', S[c]='C'
        long[] contrib = new long[N + 1];

        for (int a = 0; a < N; a++) {
            if (S.charAt(a) == 'D') {
                for (int c = a + 2; c < N; c++) {
                    if (S.charAt(c) == 'C') {
                        int d = c - a;
                        contrib[d] += prefM[c] - prefM[a + 1];
                    }
                }
            }
        }

        // prefix sum: ans[k] = sum of contrib[2..k-1]
        long[] prefContrib = new long[N + 2];
        for (int d = 2; d <= N; d++) {
            prefContrib[d] = prefContrib[d - 1] + contrib[d];
        }
        // answer for query k = prefContrib[k-1] (sum of contrib[2..k-1])

        int Q = Integer.parseInt(br.readLine().trim());
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < Q; i++) {
            int k = Integer.parseInt(br.readLine().trim());
            long ans = (k - 1 <= N) ? prefContrib[k - 1] : prefContrib[N];
            sb.append(ans).append('\n');
        }
        System.out.print(sb);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Fast scanner
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            if (c == -1) return null;
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        String first = fs.next();
        if (first == null) return;

        int N = Integer.parseInt(first);
        String S = fs.next();
        int Q = fs.nextInt();

        StringBuilder out = new StringBuilder();

        for (int qi = 0; qi < Q; qi++) {
            int k = fs.nextInt();

            long ans = 0L;

            long dCount = 0L;   // number of 'D' in current window [i-k+1, i-1]
            long mCount = 0L;   // number of 'M' in current window
            long dmCount = 0L;  // number of pairs (D,M) in current window with D before M

            for (int i = 0; i < N; i++) {
                int outIdx = i - k;
                if (outIdx >= 0) {
                    char ch = S.charAt(outIdx);
                    if (ch == 'D') {
                        dCount--;
                    } else if (ch == 'M') {
                        // This M contributed with all D currently before it in the window at its insertion time.
                        // When removing it, subtract the number of D that are still before it in the current window.
                        dmCount -= dCount;
                        mCount--;
                    }
                }

                char ch = S.charAt(i);
                if (ch == 'D') {
                    dCount++;
                } else if (ch == 'M') {
                    dmCount += dCount;
                    mCount++;
                } else if (ch == 'C') {
                    ans += dmCount;
                }
            }

            out.append(ans).append('\n');
        }

        System.out.print(out.toString());
    }
